import org.junit.Test;
import static org.mockito.Mockito.mock;

public class OnlineStockSpanTest {

    @Test
    public void next_test() {
        OnlineStockSpan stock = new OnlineStockSpan();
        int price = 1;
        int[] prices = {2, 6};
        int expected = 3;
        stock.next(10); // Using actual price instead of null
        assertEquals(expected, stock.price);
    }

    @Test
    public void next_test_withNullPrice() {
        OnlineStockSpan stock = new OnlineStockSpan();
        int price = null;
        int[] prices = {2, 6};
        stock.next(price);
    }

    @Test
    public void next_test_withNoPrices() {
        OnlineStockSpan stock = new OnlineStockSpan();
        int price = 10;
        int[] prices = {};
        stock.price = price; // Using actual price instead of null
        stock.next(prices[0]);
    }

    @Test
    public void calculateSpans_test() {
        OnlineStockSpan stock = new OnlineStockSpan();
        int[] prices = {2, 6};
        int[][] result = {{0, 1}, {3, 4}};
        stock.price = prices[0];
        stock.next(prices[1]);
        assertEquals(result[0][0], stock.price);
    }

    @Test
    public void calculateSpans_test_withEmptyPrices() {
        OnlineStockSpan stock = new OnlineStockSpan();
        int[] prices = {};
        int[][] result = {{0, 1}, {2, 3}};
        for (int i : prices) {
            stock.price = i;
            stock.next(prices);
            assertEquals(result[0][0], stock.price);
        }
    }

    @Test
